EXEC tSQLt.NewTestClass 'OrderTests';
GO
CREATE PROCEDURE OrderTests.[test GetOrderTotal sums line amounts]
AS
BEGIN
    EXEC tSQLt.FakeTable 'dbo.OrderLines';
    INSERT INTO dbo.OrderLines (OrderId, Qty, Price) VALUES (1, 2, 10.00), (1, 1, 5.00);

    DECLARE @actual DECIMAL(12,2) = dbo.GetOrderTotal(1);

    EXEC tSQLt.AssertEquals @Expected = 25.00, @Actual = @actual;
END;
GO
EXEC tSQLt.Run 'OrderTests';
